// Extracts the words of every mock screen into design/copy/<screen>.json:
// one source for the words, as design/tokens.json is for the look. A screen
// in code says copy.<screen>.<id> (generated by scripts/design/generate.mjs
// from these files), never the words themselves, so changing copy means
// changing the mock and regenerating, in one pull request.
// Usage: node scripts/design/copy-extract.mjs [--check] [--mocks DIR] [--out DIR]
//   (no flag) writes design/copy/<screen>.json from design/mocks/**/*.html
//   --check   exits 1 when a copy file is stale against its mocks (content,
//             not timestamps) or has no mock left, and names each; writes nothing
// What is a string: every visible text node (script, style, svg, head and
// template contents are not), and the alt, aria-label, placeholder and title
// attributes, and an input's value. Pure numbers, dates and strings with no
// letter (punctuation, symbols) are skipped.
// The id: the element's data-copy attribute when it has one (the whole text
// inside it is one string), else a slug of the text: lowercase, words joined
// by hyphens, cut at 40 characters, suffixed -2, -3 when two texts collide.
// A pair (Name and NameDark) is one screen, name.json; a string only one of
// the two has is listed under _only. A file whose name starts with "_" is a
// partial, not a screen.
import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync, statSync } from "node:fs";
import { dirname, join, relative, isAbsolute, basename } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const args = process.argv.slice(2);
const opt = (name, dflt) => { const i = args.indexOf(name); return i >= 0 && args[i + 1] ? args[i + 1] : dflt; };
const check = args.includes("--check");
const abs = (p) => (isAbsolute(p) ? p : join(root, p));
const mocksDir = abs(opt("--mocks", "design/mocks"));
const outDir = abs(opt("--out", "design/copy"));
const show = (p) => { const r = relative(root, p).replace(/\\/g, "/"); return r.startsWith("..") ? p.replace(/\\/g, "/") : r; };

// ---------- reading HTML (no dependencies: a small tokenizer is enough for mocks)
const NAMED = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " ", hellip: "…", mdash: "—", ndash: "–", middot: "·", rsquo: "’", lsquo: "‘", rdquo: "”", ldquo: "“", copy: "©", reg: "®", trade: "™", bull: "•", times: "×", rarr: "→", larr: "←", deg: "°", euro: "€", pound: "£" };
const decode = (s) => s.replace(/&(#x[0-9a-fA-F]+|#[0-9]+|[a-zA-Z]+);/g, (m, e) => {
  if (e[0] === "#") { const n = e[1] === "x" || e[1] === "X" ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10); try { return String.fromCodePoint(n); } catch { return m; } }
  return NAMED[e] ?? m;
});
const squash = (s) => s.replace(/[\s ]+/g, " ").trim();
const VOID = new Set(["area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "source", "track", "wbr"]);
const HIDDEN = new Set(["script", "style", "svg", "head", "template", "noscript", "helmet", "title"]);
// Inline elements join their text to the text around them: "Hello <b>you</b>" is one string.
const INLINE = new Set(["b", "i", "em", "strong", "small", "u", "mark", "sup", "sub", "code", "abbr", "s", "q", "a", "br", "wbr"]);
const ATTRS = ["alt", "aria-label", "placeholder", "title"];
const VALUE_TYPES = new Set(["", "text", "submit", "button", "reset", "search", "email", "tel", "url"]);

function parseAttrs(src) {
  const out = {};
  const re = /([^\s=\/>"']+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?/g;
  let m;
  while ((m = re.exec(src))) out[m[1].toLowerCase()] = decode(m[2] ?? m[3] ?? m[4] ?? "");
  return out;
}

// Each visible string in document order as { text, copyId?, attr? }.
function strings(html) {
  const found = [];
  const stack = []; // { tag, hidden, capture }
  let buf = "";
  const hidden = () => stack.some((e) => e.hidden);
  const capture = () => { for (let i = stack.length - 1; i >= 0; i--) if (stack[i].capture) return stack[i]; return null; };
  const flush = () => { const t = squash(buf); buf = ""; if (t) found.push({ text: t }); };
  const addText = (t) => { if (hidden()) return; const c = capture(); if (c) c.capture.text += t; else buf += t; };
  const re = /<!--[\s\S]*?-->|<!\[CDATA\[[\s\S]*?\]\]>|<![^>]*>|<\/?([a-zA-Z][\w:-]*)((?:[^>"']|"[^"]*"|'[^']*')*)>/g;
  let last = 0, m;
  while ((m = re.exec(html))) {
    addText(decode(html.slice(last, m.index)));
    last = re.lastIndex;
    if (!m[1]) continue;
    const tag = m[1].toLowerCase();
    const closing = m[0][1] === "/";
    if (closing) {
      const i = stack.map((e) => e.tag).lastIndexOf(tag);
      if (i < 0) continue;
      while (stack.length > i) {
        const e = stack.pop();
        if (e.capture) { const t = squash(e.capture.text); if (t) found.push({ text: t, copyId: e.capture.id }); }
      }
      if (!INLINE.has(tag) && !capture()) flush();
      continue;
    }
    const attrs = parseAttrs(m[2] || "");
    const selfClose = /\/\s*$/.test(m[2] || "") || VOID.has(tag);
    if (!INLINE.has(tag) && !capture()) flush();
    const isHidden = HIDDEN.has(tag) || attrs.hidden !== undefined || attrs["aria-hidden"] === "true";
    if (!hidden() && !isHidden) {
      const dc = attrs["data-copy"];
      const attrStrings = ATTRS.filter((a) => attrs[a] !== undefined).map((a) => [a, attrs[a]]);
      if (tag === "input" && attrs.value !== undefined && VALUE_TYPES.has((attrs.type || "").toLowerCase())) attrStrings.push(["value", attrs.value]);
      attrStrings.forEach(([a, v], k) => {
        const t = squash(v);
        if (!t) return;
        // A void element's first string takes the data-copy id itself; the rest add the attribute.
        found.push({ text: t, copyId: dc ? (selfClose && k === 0 ? dc : `${dc}-${a}`) : undefined, attr: a });
      });
      if (!selfClose) stack.push({ tag, hidden: false, capture: dc && !capture() ? { id: dc, text: "" } : null });
    } else if (!selfClose) stack.push({ tag, hidden: true, capture: null });
  }
  addText(decode(html.slice(last)));
  while (stack.length) { const e = stack.pop(); if (e.capture) { const t = squash(e.capture.text); if (t) found.push({ text: t, copyId: e.capture.id }); } }
  flush();
  return found;
}

// ---------- what counts as words
const MONTH = "(jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec|january|february|march|april|june|july|august|september|october|november|december)";
const WEEKDAY = "(mon|tue|tues|wed|thu|thur|thurs|fri|sat|sun|monday|tuesday|wednesday|thursday|friday|saturday|sunday)";
const DATE_RES = [
  /^\d{4}-\d{2}-\d{2}([t ]\d{1,2}:\d{2}(:\d{2})?)?$/i,
  /^\d{1,2}[\/.]\d{1,2}([\/.]\d{2,4})?$/,
  /^\d{1,2}:\d{2}(:\d{2})?\s*(am|pm)?$/i,
  new RegExp(`^(${WEEKDAY},?\\s+)?${MONTH}\\.?\\s+\\d{1,2}(st|nd|rd|th)?(,?\\s+\\d{4})?(,?\\s+\\d{1,2}(:\\d{2})?\\s*(am|pm)?)?$`, "i"),
  new RegExp(`^(${WEEKDAY},?\\s+)?\\d{1,2}\\s+${MONTH}\\.?(,?\\s+\\d{4})?$`, "i"),
  new RegExp(`^${MONTH}\\.?\\s+\\d{4}$`, "i"),
  new RegExp(`^${WEEKDAY}\\.?$`, "i"),
];
export const isWords = (t) => /\p{L}/u.test(t) && !DATE_RES.some((r) => r.test(t)) && !/^[\d\s.,:%+\-−–\/$€£¥#×x]+$/i.test(t);

export const slug = (t) => {
  let s = t.normalize("NFKD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
  if (s.length > 40) s = s.slice(0, 40).replace(/-+$/, "");
  return s || "text";
};

// The strings of one file, keyed: { id: text } in document order.
function keyed(html) {
  const byId = new Map(), idOfText = new Map(), explicit = new Map();
  const take = (base, text) => { let id = base, n = 2; while (byId.has(id) && byId.get(id) !== text) id = `${base}-${n++}`; byId.set(id, text); return id; };
  for (const s of strings(html)) {
    if (!isWords(s.text)) continue;
    if (s.copyId) {
      if (explicit.get(s.copyId) === s.text) continue;
      explicit.set(s.copyId, s.text);
      take(s.copyId, s.text);
    } else {
      if (idOfText.has(s.text)) continue;
      idOfText.set(s.text, take(slug(s.text), s.text));
    }
  }
  return byId;
}

// ---------- screens
function walk(dir) {
  const out = [];
  for (const name of readdirSync(dir).sort()) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) { if (name !== "node_modules" && !name.startsWith(".")) out.push(...walk(p)); }
    else if (/\.html?$/i.test(name) && !name.startsWith("_")) out.push(p);
  }
  return out;
}
const kebab = (s) => s.replace(/([a-z0-9])([A-Z])/g, "$1-$2").replace(/([A-Z]+)([A-Z][a-z])/g, "$1-$2").replace(/[^A-Za-z0-9]+/g, "-").replace(/^-+|-+$/g, "").toLowerCase();
const stem = (p) => basename(p).replace(/(\.dc)?\.html?$/i, "");

function screens(files) {
  const byStem = new Map(files.map((f) => [stem(f), f]));
  const out = new Map();
  for (const f of files) {
    const s = stem(f);
    const light = /Dark$/.test(s) && byStem.has(s.slice(0, -4)) ? null : f;
    if (!light) continue; // the dark half, read with its light file
    const dark = byStem.get(s + "Dark") || null;
    let name = kebab(s);
    if (out.has(name)) { let n = 2; while (out.has(`${name}-${n}`)) n++; name = `${name}-${n}`; }
    out.set(name, { light, dark });
  }
  return out;
}

function render(name, { light, dark }) {
  const a = keyed(readFileSync(light, "utf8"));
  const b = dark ? keyed(readFileSync(dark, "utf8")) : new Map();
  const doc = {
    _generated: `Generated by scripts/design/copy-extract.mjs from ${[light, dark].filter(Boolean).map(show).join(" and ")}. Do not edit; change the mock and run: node scripts/design/copy-extract.mjs`,
  };
  const only = {};
  if (dark) {
    const lightOnly = [...a.keys()].filter((k) => b.get(k) !== a.get(k));
    const darkOnly = [...b.keys()].filter((k) => a.get(k) !== b.get(k));
    if (lightOnly.length) only.light = lightOnly;
    if (darkOnly.length) only.dark = darkOnly;
  }
  if (Object.keys(only).length) doc._only = only;
  for (const [k, v] of a) doc[k] = v;
  // a dark-only string keeps its own id, suffixed if the light file holds the id with other words
  for (const [k, v] of b) {
    if (a.get(k) === v) continue;
    let id = k, n = 2;
    while (doc[id] !== undefined && doc[id] !== v) id = `${k}-${n++}`;
    if (id !== k && doc._only && doc._only.dark) doc._only.dark = doc._only.dark.map((x) => (x === k ? id : x));
    doc[id] = v;
  }
  return JSON.stringify(doc, null, 2) + "\n";
}

if (!existsSync(mocksDir)) {
  console.log(`${show(mocksDir)} does not exist; no copy to extract.`);
  process.exit(0);
}
const plan = [...screens(walk(mocksDir))].map(([name, pair]) => [join(outDir, `${name}.json`), render(name, pair)]);
const wanted = new Set(plan.map(([p]) => p));
let stale = 0, wrote = 0;
for (const [p, text] of plan) {
  let cur = "";
  try { cur = readFileSync(p, "utf8"); } catch {}
  if (cur.replace(/\r\n/g, "\n") === text) continue;
  if (check) { console.error(`${show(p)} is out of date with its mocks.`); stale++; }
  else { mkdirSync(dirname(p), { recursive: true }); writeFileSync(p, text); wrote++; }
}
if (existsSync(outDir)) {
  for (const name of readdirSync(outDir).sort()) {
    const p = join(outDir, name);
    if (name.endsWith(".json") && !wanted.has(p)) {
      if (check) stale++;
      console.error(`${show(p)} has no mock any more; move it aside.`);
    }
  }
}
if (check) {
  if (stale) console.error("Run: node scripts/design/copy-extract.mjs, then node scripts/design/generate.mjs, and commit the result with the mock.");
  else console.log(`Copy files are current (${plan.length}).`);
} else console.log(`${plan.length} screens, ${wrote} copy files written to ${show(outDir)}.`);
process.exit(stale ? 1 : 0);
